abilitySting = function(ship){
  let target = findClosestEnemy(ship,12)
  target.custom.poisoned = true;ship.custom.poisoning = true;target.custom.inAbility = true;ship.custom.inAbility = true;
  ship.set({invulnerable:100})
  target.set({invulnerable:50})
  setTimeout( () => { target.custom.poisoned = false; ship.custom.poisoning = false; target.custom.inAbility = false; ship.custom.inAbility = false; }, 8000 )}
abilityPull = function(ship,strength,multiple=0){
  if (!multiple) { closestship = findClosestPlayer(ship)[0] }
  else { closestship = findClosestPlayer(ship,multiple)[1] }
  if (!multiple) {angl = angle(closestship.x,closestship.y,ship.x,ship.y);
    if (closestship.x != ship.x) { DASH(closestship,angl,strength,1)  }}
  else {
    for ( let Qship of closestship ){
      angl = angle(Qship.x,Qship.y,ship.x,ship.y);
      if (Qship.x != ship.x) { DASH(Qship,angl,strength,5) }}}};
