// SPECIAL MODE STUFF



manageAbilities = function(ship){
  if (ship.type == 754 && ship.generator < 300) { abilityPenetrator(ship); }
  if (ship.type == 652 && ship.generator < 240) { abilityPiercer(ship); }
  if (ship.custom.inAbility){
    if (ship.custom.spam && ship.alive){
      ship.emptyWeapons();
      game.addCollectible({code:11,x:ship.x+ship.vx*2,y:ship.y+ship.vy*2});
    }
    if (ship.custom.healing){
      let affectedships = findClosestPlayer([ship.custom.healX,ship.custom.healY],customOptions.healrange/2)[1]
    for (let Qship of affectedships){
      if (Qship.team == ship.team){damageShip(Qship,customOptions.healstrength)}
      }
    }
    if (ship.custom.poisoned) {damageShip(ship,venomstrength)}
    if (ship.custom.poisoning) {damageShip(ship,venomhealing)}
  }
  if (!ship.custom.EMP && ship.alive) { ship.custom.cooldown += 61; }
}
readyWhenAppropriate = function(ship){
  let Itype = ship.type;
  if (ship.custom.cooldown > customShips[Itype].cooldown) {
    indicator_ready.components[1].value = "Ready";
    if ([613,791,792,793].includes(Itype)){
      switch (ship.custom.synthesisStage) {
        case 1: indicator_ready.components[1].value = "1/3 Kills"; break;
        case 2: indicator_ready.components[1].value = "2/3 Kills"; break;
        default: indicator_ready.components[1].value = "Ready";break;
      }
    }
    sendUI(ship,indicator_ready);//abilityPiercer
    if (Itype == 669 && ship.custom.cooldown > customShips[669].cooldown) { abilityDetonate(ship); } // detonate ship after it gets ready
  }
}
showDashRadius = function(ship){
  Itype = ship.type;
  if (customShips[Itype].radius) { create_radius( customShips[Itype].radius ) }
    sendUI(ship,dashRadius);
    dashRadius.visible = false;
}
defaultAbility = function(ship){
  abilitydesc = "Quickdrive [X]";
  if (ship.custom.cooldown > customShips["default"].cooldown) { sendUI(ship,indicator_ready); indicator_reloading.components[1].value = Math.round((customShips["default"].cooldown-1) / 60) }
    dashRadius.visible = true;
    dashRadius.position = [29.8,16,50,85];
    dashRadius.components[0].position = [0,0,81,81];
    sendUI(ship,dashRadius);
    dashRadius.visible = false;
}
reloadTimer = function(ship){
  let Itype = ship.type;
  if ((Itype in customShips) && ship.custom.cooldown < customShips[Itype].cooldown && Itype != 669){// if you're synthesis and you have 0 kills, say "kill"
    if ([613,791,792,793].includes(Itype)){
      if (ship.custom.synthesisStage === 0) {indicator_reloading.components[1].value = "Kill!"}
      if (ship.custom.synthesisStage >= 1) {ship.custom.cooldown = 99999}
    } else if ([641,799].includes(Itype)){
      switch (ship.custom.megalodonStage) {
        case 0: indicator_reloading.components[1].value = "0/3 Kills"; break;
        case 1: indicator_reloading.components[1].value = "1/3 Kills"; break;
        case 2: indicator_reloading.components[1].value = "2/3 Kills"; break;
        default: indicator_reloading.components[1].value= "3/3 Kills"; ship.custom.cooldown = 99999; break;
      }
    } else {
      indicator_reloading.components[1].value = Math.round((customShips[Itype].cooldown - ship.custom.cooldown) / 60);
    }
    sendUI(ship,indicator_reloading);
  }
  // same as above, but for default ship
  if (!(Itype in customShips) && ship.custom.cooldown < customShips["default"].cooldown && Itype != 708)
  {
    indicator_reloading.components[1].value = Math.round((customShips["default"].cooldown - ship.custom.cooldown) / 60);
    sendUI(ship,indicator_reloading);
  }
}
prepareShip = function(ship){
  if (ship.type == 669) { ship.set({type:619})}
  ship.custom.timer = 0;
  ship.custom.EMP = false
  ship.custom.healing = false
  //if (ship.type > 699) { ship.set({type:ship.type-100}) }
  ship.custom.mirrored = false;
  ship.custom.synthesisStage = 0;
  ship.custom.megalodonStage = 0;
  ship.custom.poisoned = false;
  ship.custom.poisoning = false;
  ship.custom.inAbility = false;
  ship.custom.cooldown = 0;
  sendUI(ship,indicator_reloading);
  ship.set({idle:false,collider:true});
  ship.set({crystals:Math.floor(Math.floor(ship.type/100)**2*20/6)})
}
initializeShip = function(ship){
  ship.custom.mirrored = false;
  ship.custom.timer = 0;
  ship.custom.synthesisStage = 0;
  ship.custom.megalodonStage = 0;
  ship.custom.inAbility = false;
  ship.custom.TRUEteam = ship.team;
  ship.custom.init = true;
  ship.custom.cooldown = 0;
  sendUI(ship,indicator_reloading);
  let instructor_paragaph = "Greetings, Commander.\nYour ship is equipped with a special ability module.\nPress [X] to activate it."// Capture the point in the middle to win! Stand inside the point to capture it."
  switch (game.options.hues[ship.custom.TRUEteam]){
    case 180: instructor_type = "Lucina"; break;
    case 0: instructor_type = "Zoltar"; break;
    case 270: instructor_type = "Kan"; break;
    case 90: instructor_type = "Maria"; break;
    default: instructor_type = "Zoltar"; break;
  }
  ship_instructor(ship, instructor_paragaph, instructor_type,0,10);
}



// TICK, EVENT



this.tick = function(game) {

  if (game.step % 60 === 0) { // every second
    
    for (let ship of game.ships) {// ship = every ship
      // crystal cap
      //if ( ship.crystals > Math.floor(ship.type/100)**2*20 ) { ship.set({crystals:Math.floor(ship.type/100)**2*20})}
      // on spawn
      if (!ship.custom.init){ initializeShip(ship);prepareShip(ship); };
      ship.custom.timer++;
      manageAbilities(ship);
      if (game.ships.length) {
        var abilitydesc = "UNDEFINED";
        let Itype = ship.type
        if (Itype in customShips) { // if the ship's ship is defined in customShips
          abilitydesc = customShips[Itype].abilityname; // change ability description depending on type
          showDashRadius(ship);
          readyWhenAppropriate(ship);
        } else { defaultAbility(ship); }
        ability.components[1].value = abilitydesc;
        sendUI(ship,ability);
        reloadTimer(ship);
      }
    }
  }
 if (game.step % 60 === 0) {
  BiteDmg = BiteDmg+0.025
   
}   // every second
 if (game.step % 15 === 0) {
 if (spam === true){
        ship.emptyWeapons();
        game.addCollectible({code:11,x:ship.x,y:ship.y});
      }
   
} 
 
};

defaultability = function(ship){
  if ( ship.custom.cooldown > customShips["default"].cooldown ){
    abilityQuickdrive(ship);
    ship.custom.cooldown = 0;
    indicator_reloading.components[1].value = Math.round((customShips["default"].cooldown-1) / 60);
    sendUI(ship,indicator_reloading);
  }
}

this.event = function(event,game){
  let ship = event.ship; 
  switch (event.name){
    case "ui_component_clicked":
      var component = event.id;
      if (component == "ability" && !ship.custom.EMP && ship.alive){
        let ship = event.ship;
        let Itype = ship.type;
        if (Itype == 669 && ship.custom.cooldown > customShips[669].cooldown/3 ) { abilityDetonate(ship); }
        if ( !(Itype in customShips) ){
          defaultability(ship)
      }else{
        if ( ship.custom.cooldown > customShips[Itype].cooldown ){
          customShips[Itype].func(ship);
          ship.custom.cooldown = 0;
          if (customShips[Itype].abilityname == "Mirror [X]") { ship.custom.cooldown = customShips[HE[2]].cooldown - 5*60 }
          indicator_reloading.components[1].value = Math.round((customShips[Itype].cooldown-1) / 60);
          if (Itype != 619) { sendUI(ship,indicator_reloading); } else { sendUI(ship,indicator_ready); }
          }
        }
      }
      break;
    case "ship_destroyed":
      prepareShip(ship);
      if (event.killer){
        if ([613,691,692,693].includes(event.killer.type) && event.killer.custom.synthesisStage < 3) {// max is 3
          // if the killer is using synthesis or its abilities, ship.custom.synthesisStage increases
          event.killer.custom.synthesisStage++;
        }
        if (641 == event.killer.type && event.killer.custom.megalodonStage < 3) {
          event.killer.custom.megalodonStage++;
        }
      }
      break;
  }
};



// UTILITY/MODERATION FUNCTIONS



heal = function(id){init(game.ships[id].type,id)}
killaliens = function(){
for(var i=0; i<game.aliens.length; i++)
   game.aliens[i].set({
     kill:true
   });
};
print = function(what){ // wait this is not python
  game.modding.terminal.echo(what);
};

say = function(saysWhat, duration, instructor = "Zoltar"){
  for(let ship of game.ships){
    ship.instructorSays(saysWhat, instructor);
    setTimeout(() => { ship.hideInstructor() }, duration*1000);
  }
  game.modding.terminal.echo("Message: \""+saysWhat+"\"");
};
hide = function(){
    for(var i=0; i<game.ships.length; i++){
        game.ships[i].hideInstructor();
    }
};
init = function(lvl,who=0){
  if (lvl < 199){
    gem = 20;
  }
  else if (lvl < 299){
    gem = 80;
  }
  else if (lvl < 399){
    gem = 180;
  }
  else if (lvl < 499){
    gem = 320;
  }
  else if (lvl < 599){
    gem = 500;
  }
  else if (lvl < 699){
    gem = 720;
  }
  else if (lvl < 710){
    gem = 980;
  }
  else if (lvl > 715){
    gem = 999999;
  }
  game.ships[who].set({
    type:lvl,
    stats:88888888,
    shield:1000,
    crystals:gem
  });
};
kill = function(who){
  game.ships[who].set({kill:true});
};
sun = function(wat){
  game.ships[wat].set({x:0,y:0,vx:0,vy:0});
};
tp = function(xx,yy){
  game.ships[0].set({x:xx,y:yy});
};
tpto = function(who){
  ship = game.ships[who];
  game.ships[0].set({x:ship.x,y:ship.y});
};
tpxtoy = function(who,towho){
  ship = game.ships[towho];
  game.ships[who].set({x:ship.x,y:ship.y});
};
sunall = function(){
for(var i=0; i<game.ships.length; i++)
  game.ships[i].set({x:0,y:0});
};
kick = function(i,reason="Unspecified."){
  game.ships[i].gameover({"You were kicked for reason: ":reason,"Your name: ":game.ships[i].name,"Score: ":game.ships[i].score});
};
info = function(){
  game.modding.terminal.echo('Total amount of aliens:'+game.aliens.length)
  game.modding.terminal.echo('Total amount of asteroids:'+game.asteroids.length)
  game.modding.terminal.echo('Total amount of players:'+game.ships.length)
  for (nn=0;nn<game.ships.length;nn++){
    game.modding.terminal.echo(nn+": "+game.ships[nn].name+', type: '+game.ships[nn].type+' X,Y: '+game.ships[nn].x+', '+game.ships[nn].y);
  }
};
teamx = function(id,tem){
  let ship = game.ships[id];
  ship.set({team:tem,hue:game.options.hues[tem]});
  ship.custom.TRUEteam = tem;
}
reload = function(shipid){ game.ships[shipid].custom.cooldown = 99999999; }

/*
MODERATION FUNCTION TUTORIAL
1. info()-  --  -- - type info() in the console to see stats about the game and see ship ids
2. heal(id) --  -- - restore health, gems and stats for the ship of your choosing (ID)
3. init(type,id)-- - sets a player of your choosing (ID) to a ship of any type (TYPE)
4. kill(id) --  -- - kills a player (ID)
5. teamx(id,team)- - changes chosen player(ID)'s TEAM: 1 = blue, 0 = red
6. sunall() --  -- - teleports all players to the sun
7. kick(id,reason) - kicks a player of a certain ID from the game
8. tpto(id) --  -- - teleports player with ID 0 (you) to player with id of your choosing (ID)
9. tpxtoy(id1,id2) - teleports player with ID1 to player with ID2
10.killaliens() -- - kills all aliens
11.say(text,duration)displays TEXT to all players for DURATION (in seconds)
12.hide()   --  -- - hides TEXT from all players
*/
